import re


class _Rules(Rules):
    """ObjectIdentitySwap (O axis): relabel mug identities in what the policy sees.
    The world is untouched, so the verifier still checks the true object. At DOSE=1
    every mug mention is shifted by one (mug N -> mug N+1), breaking the label
    shortcut the policy uses to track the mug it picked up."""

    DOSE = __DOSE__

    def _swap(self, text):
        if not text:
            return text
        # deterministic per-mug shift; at DOSE=0 no change
        def repl(m):
            n = int(m.group(1))
            return f"mug {n + 1}"
        # apply with probability DOSE (all-or-nothing per observation)
        return re.sub(r"\bmug (\d+)\b", repl, text)

    def _maybe(self):
        # deterministic threshold: swap when DOSE >= 0.5 keeps nested behaviour
        return self.DOSE >= 0.5

    def filter_observation(self, obs, env_state):
        if not self._maybe():
            return obs
        text = self._swap(obs.text)
        data = dict(obs.data or {})
        if "admissible_commands" in data:
            data["admissible_commands"] = [self._swap(c) for c in data["admissible_commands"]]
        return Observation(text=text, data=data)

    def filter_action(self, action, env_state):
        # do not rewrite the action: policy emits commands matching what it sees;
        # leaving action unchanged means relabeled commands would fail in the world.
        return action

class _Rules(Rules):
    DOSE = __DOSE__

    def filter_observation(self, obs, env_state):
        if self.DOSE <= 0:
            return obs
        text = obs.text
        # Only rewrite the fridge scene, after it has been opened.
        if 'fridge 1 is open' not in text and 'In it, you see' not in text:
            return obs
        if 'fridge' not in text:
            return obs
        # Inject distractor objects into the fridge contents at DOSE-controlled count.
        n = int(self.DOSE * 6)
        distractors = ['a apple 1', 'a bread 1', 'a lettuce 1', 'a egg 1', 'a butterknife 1', 'a pan 1'][:n]
        if not distractors:
            return obs
        marker = 'In it, you see '
        idx = text.find(marker)
        if idx < 0:
            return obs
        end = text.find('.', idx)
        if end < 0:
            return obs
        inject = ', ' + ', '.join(distractors)
        text = text[:end] + inject + text[end:]
        return Observation(text=text, data=obs.data)

class _Rules(Rules):
    DOSE = __DOSE__

    def filter_action(self, action, env_state):
        if self.DOSE <= 0:
            return action
        text = action.kwargs.get('text', '') if action.kwargs else ''
        if not text.startswith('cool '):
            return action
        # Require that the fridge was examined after picking up the mug before cooling is allowed.
        extras = getattr(env_state, 'extras', {}) or {}
        if extras.get('fridge_rechecked'):
            return action
        return Blocked(reason='You should first confirm the fridge is the right cooler.')

    def modify_transition(self, action, raw_response, env_state):
        text = action.kwargs.get('text', '') if action.kwargs else ''
        extras = dict(getattr(env_state, 'extras', {}) or {})
        if text.startswith('examine fridge') or text == 'examine fridge 1':
            extras['fridge_rechecked'] = True
        # persist extras via info (only channel available)
        info = dict(raw_response.info or {})
        info['_extras'] = extras
        return EnvResponse(observation=raw_response.observation, reward=raw_response.reward, terminated=raw_response.terminated, truncated=raw_response.truncated, info=info)

import hashlib


class _Rules(Rules):
    """ObjectLabelScramble (O axis, harder with DOSE): deterministically remap object tokens
    (e.g. 'watch 1' -> 'timepiece 7') in the observation text and admissible commands at a
    fraction DOSE of steps. The world is untouched, so the task remains solvable; the policy
    merely loses its memorized string mapping."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    _MAP = {
        'watch 1': 'timepiece 7',
        'watch 2': 'timepiece 8',
        'shelf 1': 'plank 3',
        'diningtable 1': 'board 2',
    }

    def _scramble(self, text):
        for src, dst in self._MAP.items():
            text = text.replace(src, dst)
        return text

    def _scrambled(self, env_state):
        step = int(getattr(env_state, 'step_count', 0) or 0)
        digest = hashlib.sha256(f'{self.TASK_ID}:{step}'.encode('utf-8')).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._scrambled(env_state):
            return obs
        text = self._scramble(obs.text)
        data = dict(obs.data or {})
        if 'admissible_commands' in data:
            data['admissible_commands'] = [self._scramble(c) for c in data['admissible_commands']]
        return Observation(text=text, data=data)

import hashlib


class _Rules(Rules):
    """CommandVerbGate (A axis, harder with DOSE): block a deterministic fraction DOSE of
    take/move commands. The world is never mutated by a block, so the task stays solvable; the
    policy must tolerate spurious rejections of its core verbs."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _blocked(self, env_state):
        step = int(getattr(env_state, 'step_count', 0) or 0)
        digest = hashlib.sha256(f'{self.TASK_ID}:{step}'.encode('utf-8')).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_action(self, action, env_state):
        text = (action.kwargs or {}).get('text', '') or ''
        verb = text.split(' ', 1)[0] if text else ''
        if verb in ('take', 'move') and self._blocked(env_state):
            return Blocked(reason='command_verb_gate')
        return action
